package com.johnny.hotel.ar;
import com.johnny.hotel.ar.ArModels.*;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/finance/ar") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')") public class ArController {private final ArService service;
 @GetMapping("/accounts")public Result<PageResult<java.util.Map<String,Object>>>accounts(@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.accounts(page,pageSize));}
 @PostMapping("/accounts")public Result<AccountView>create(@Valid@RequestBody AccountRequest r){return Result.success(service.create(r));}@PostMapping("/accounts/{id}/status/{status}")public Result<AccountView>status(@PathVariable Long id,@PathVariable String status){return Result.success(service.status(id,status));}@GetMapping("/accounts/{id}")public Result<AccountView>get(@PathVariable Long id){return Result.success(service.get(id));}
 @PostMapping("/accounts/{accountId}/folios/{folioId}/transfer")public Result<ArLedgerEntry>transfer(@PathVariable Long accountId,@PathVariable Long folioId,@Valid@RequestBody TransferRequest r){return Result.success(service.transfer(accountId,folioId,r));}@PostMapping("/accounts/{id}/payments")public Result<ArLedgerEntry>pay(@PathVariable Long id,@Valid@RequestBody PaymentRequest r){return Result.success(service.pay(id,r));}@PostMapping("/accounts/{id}/credits")public Result<ArLedgerEntry>credit(@PathVariable Long id,@Valid@RequestBody CreditRequest r){return Result.success(service.credit(id,r));}@GetMapping("/accounts/{id}/statement")public Result<PageResult<ArLedgerEntry>>statement(@PathVariable Long id,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.statement(id,page,pageSize));}
}
